ID = "math_ex_ch6_complexes_6"
R3 = 3 ** .5


def figure(a, ta):
    b = a.conjugate()
    return plan("Les points A(a) et B(b), b = ā", f"a = {ta} ; B est le symétrique de A par rapport à l'axe réel.",
                [("A", a.real, a.imag, "cyan", "se"), ("B", b.real, b.imag, "orange", "ne")], xs=(-1, 4), ys=(-3, 3),
                autres=[{"f": "ligne", "pts": [[0, 0], [a.real, a.imag]], "couleur": "cyan", "trait": "pointille"},
                        {"f": "ligne", "pts": [[0, 0], [b.real, b.imag]], "couleur": "orange", "trait": "pointille"}])


def ass_conjugue():
    G = [("1", "z + z̄"), ("2", "z − z̄"), ("3", "z·z̄")]
    D = [("a", "2 Re(z)"), ("b", "2i Im(z)"), ("c", "|z|²"), ("d", "0")]
    C = {"1": "a", "2": "b", "3": "c"}
    R = {
      "1-a": ("Oui : les parties imaginaires s'annulent, il reste deux fois la partie réelle.", "برافو: les parties imaginaires كيتحيدو، وكيبقى deux fois la partie réelle."),
      "1-b": ("Dans la somme, ce sont les termes en i qui s'annulent : il ne reste pas de i.", "لا، فـ la somme، les termes فيهم i هما اللي كيتحيدو: ما كيبقاش i."),
      "1-c": ("|z|² vient du produit z·z̄, pas de la somme.", "لا، le module au carré كيجي من le produit، ماشي من la somme."),
      "1-d": ("La somme est nulle seulement si la partie réelle est nulle.", "لا، la somme كتكون zéro غير يلا كانت la partie réelle zéro."),
      "2-a": ("Dans la différence, ce sont les parties réelles qui s'annulent.", "لا، فـ la différence، les parties réelles هما اللي كيتحيدو."),
      "2-b": ("Oui : a + ib − (a − ib) = 2ib.", "برافو: a plus i b، moins، a moins i b، égale deux i b."),
      "2-c": ("|z|² vient du produit, pas de la différence.", "لا، le module au carré كيجي من le produit، ماشي من la différence."),
      "2-d": ("La différence est nulle seulement si z est réel.", "لا، la différence كتكون zéro غير يلا كان z réel."),
      "3-a": ("2 Re(z) est la somme z + z̄, pas le produit.", "لا، deux fois la partie réelle هي la somme، ماشي le produit."),
      "3-b": ("Le produit z·z̄ est réel : il n'a pas de i.", "لا، le produit z fois z barre réel: ما فيهش i."),
      "3-c": ("Oui : z·z̄ = a² + b² = |z|².", "برافو: z fois z barre، égale a carré plus b carré، يعني le module au carré."),
      "3-d": ("z·z̄ = |z|² n'est nul que pour z = 0.", "لا، z fois z barre كيكون zéro غير ملي z égale zéro."),
    }
    return association("fa_c6_5", "Plus facile : les trois règles du conjugué", "Relie chaque expression à ce qu'elle vaut (z = a + ib).",
      "سؤال ساهل: ربط كل expression مع la valeur ديالها.", "Relie chaque expression à ce qu'elle vaut.", G, D, C, R,
      ("(1 ; a) (2 ; b) (3 ; c) : 0 est de trop.", "un مع a، deux مع b، trois مع c. zéro زايد."))


